#!/usr/bin/env python3
import argparse
import json
import os
from datetime import datetime

DB_FILE = "expenses.json"

def load_expenses():
    if not os.path.exists(DB_FILE):
        return []
    with open(DB_FILE, "r") as f:
        return json.load(f)

def save_expenses(expenses):
    with open(DB_FILE, "w") as f:
        json.dump(expenses, f, indent=2)

def generate_id(date_str):
    today = datetime.strptime(date_str, "%Y-%m-%d").strftime("%Y%m%d")
    count = sum(1 for e in load_expenses() if e["id"].startswith(today))
    return f"{today}-{count+1:03d}"

def add_expense(amount, category, description=""):
    expenses = load_expenses()
    date_str = datetime.now().strftime("%Y-%m-%d")
    expense = {
        "id": generate_id(date_str),
        "date": date_str,
        "category": category,
        "amount": amount,
        "description": description
    }
    expenses.append(expense)
    save_expenses(expenses)
    print(f"Added: {amount} in {category}")

def list_expenses():
    expenses = load_expenses()
    for e in sorted(expenses, key=lambda x: x["date"]):
        print(f"{e['id']} | {e['date']} | {e['category']} | {e['amount']} | {e['description']}")

def report_month(month):
    expenses = load_expenses()
    totals = {}
    for e in expenses:
        if e["date"][5:7] == month:
            cat = e["category"]
            totals[cat] = totals.get(cat, 0) + e["amount"]
